/* @lc app=leetcode id=3249 lang=kotlin */ class Solution { fun countGoodNodes(edges: Array<IntArray>): Int = (edges.size + 1).let { n -> edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().filter { par[it] == -1 }.onEach { v -> par[v] = u } }.takeIf { it.isNotEmpty() } }.flatten().toList().let { order -> IntArray(n) { 1 }.also { sz -> order.reversed().forEach { v -> if (v != 0) sz[par[v]] += sz[v] } }.let { sz -> order.count { v -> g[v].orEmpty().filter { par[it] == v && it != 0 }.map { sz[it] }.distinct().size <= 1 } } } } } } }